generators.apply:
({context}) => {
            let hh = context.evalue.getHours();
            let ampm = 'am'
            if (hh > 12) {
              hh -= 12;
              ampm = 'pm'
            }
            let ss = context.evalue.getMinutes()
            ss = pad(ss, 2)
            return `${hh}:${ss} ${ampm}` 
          }

({g, context}) => {
            function pad(num, size) {
              num = num.toString();
              while (num.length < size) num = "0" + num;
              return num;
            }

              return `${context.evalue.getHours()}:${pad(context.evalue.getMinutes(), 2)}` 
          }

semantics.apply:
async ({context, e, s, handlerStack}) => {
            const v = (await e(context.repeats.repeats)).evalue
            for (let i = 0; i < v; ++i) {
              if (context.action) {
                await s(context.action)
              } else {
                const repeats = context.repeats
                context.repeats = undefined
                await s(context)
                context.repeats = repeats
              }
            }
          }

({objects, context, api}) => {
            context.evalue = api.newDate()
            context.format = objects.format
          }

({objects, context}) => {
